      SUBROUTINE CONDORCC     CALCULATES PARTIALS AND CONSTRAINTS FOR THIRD-ORDER FITTINGCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM10A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'UC2.CIN'CC     LOCAL VARIABLESC      REAL  RSX(6,NPVAR+1), USX(56,NPVAR+1)      REAL  UST(6,21,NPVAR+1), USS(21,6,NPVAR+1)      REAL  USSS(56,NPVAR+1), USSC(6,NPVAR+1)CC-----------------------------------------------------------      J = JCON      K = KCON      NP1 = NV1 + 1      IF (J .GE. 0) GO TO 200CC     THIRD ORDER MATRIX ELEMENT CONSTRAINTC   70 J = - J      KLM = K      K = KLM/100      LM = KLM - 100*K      LL = LM/10      M = LM - 10*LL      IF (J .GT. 6) GO TO 900      IF (K .LT. 1 .OR. K .GT. 6) GO TO 900      IF (LL .LT. 1 .OR. LL .GT. 6) GO TO 900      IF (M .LT. 1 .OR. M .GT. 6) GO TO 900      KLM = K + LL*(LL-1)/2 + M*(M+1)*(M-1)/6      DO 80 L1 = 1, NP1   80 A(L1) = 0.0      CW = 1.0/SD**2      FAC = UBEAM(K)*UBEAM(LL)*UBEAM(M)/UBEAM(J)      COC = UC2(J,KLM)*FAC      IF (NV3 .LT. 1) RETURN      A(1) = DE0 - COCC      IF (NV1 .LT. 1) GO TO 120      DO 110 N = 1, NV1      IF (.NOT. R2VP(N)) GO TO 110      A(N+1) = U2V(J,KLM,N)*FAC  110 CONTINUE  120 CALL GATHER      RETURNCC     MINIMIZATION OF CONTRIBUTION OF THIRD-ORDER ABERRATIONS TO BEAMC  200 IF (.NOT. ACCEL) CW = 1.0/SD**2CC     THIRD-ORDER CONTRIBUTIONSC     PRODUCT OF RC2 AND SIC      DO 220 L2 = 1, 6      SS = 0.0      DO 210 L1 = 1, 6      SS = SS + RC2(J,L1)*SI(L1,L2)  210 CONTINUE      RSX(1,L2) = - SS  220 CONTINUEC      DO 240 N = 1, NV1      DO 240 L2 = 1, 6      SS = 0.0      DO 230 L1 = 1, 6      SS = SS + R2V(J,L1,N)*SI(L1,L2)  230 CONTINUE      RSX(N+1,L2) = SS  240 CONTINUECC     PRODUCT OF UC2 AND SI DOUBLY CONTRACTEDC      I234 = 0      DO 260 I4 = 1, 6      SS = 0.0      DO 250 I3 = 1, I4      DO 250 I2 = 1, I3      I234 = I234 + 1      SS = SS + UC2(J,I234)*SI(I2,I3)  250 CONTINUE      USX(I4,1) = - SS  260 CONTINUEC      I234 = 0      DO 270 I4 = 1, 6      DO 270 I3 = 1, I4      DO 270 I2 = 1, I3      I234 = I234 + 1      USX(I3,1) = USX(I3,1) - UC2(J,I234)*SI(I2,I4)  270 CONTINUEC      I234 = 0      DO 280 I4 = 1, 6      DO 280 I3 = 1, I4      DO 280 I2 = 1, I3      I234 = I234 + 1      USX(I2,1)  = USX(I2,1) - UC2(J,I234)*SI(I3,I4)  280 CONTINUEC      DO 330 N = 1, NV1      I234 = 0      DO 300 I4 = 1, 6      SS = 0.0      DO 290 I3 = 1, I4      DO 290 I2 = 1, I3      I234 = I234 + 1      SS = SS + U2V(J,I234,N)*SI(I2,I3)  290 CONTINUE      USX(I4,N+1) = SS  300 CONTINUEC      I234 = 0      DO 310 I4 = 1, 6      DO 310 I3 = 1, I4      DO 310 I2 = 1, I3      I234 = I234 + 1      USX(I3,N+1) = USX(I3,N+1) + U2V(J,I234,N)*SI(I2,I4)  310 CONTINUEC      I234 = 0      DO 320 I4 = 1, 6      DO 320 I3 = 1, I4      DO 320 I2 = 1, I3      I234 = I234 + 1      USX(I2,N+1)  = USX(I2,N+1) + U2V(J,I234,N)*SI(I3,I4)  320 CONTINUE  330 CONTINUECC     MULTIPLY U X SI TO GET MATRIX PRODUCT USC      DO 335 N = 1, NP1      DO 335 I2 = 1, 6      DO 335 I34 = 1, 21      UST(I2,I34,N) = 0.0  335 CONTINUEC      I234 = 0      I34 = 0      DO 350 I4 = 1, 6      DO 350 I3 = 1, I4      I34 = I34 + 1      DO 350 I2 = 1, I3      I234 = I234 + 1      UFAC = - UC2(J,I234)      IF (UFAC .NE. 0.0) THEN        DO 340 I5 = 1, 6        UST(I5,I34,1) = UST(I5,I34,1) + UFAC*SI(I2,I5)  340   CONTINUE      ENDIF  350 CONTINUEC      DO 380 N = 1, NV1      I234 = 0      I34 = 0      DO 370 I4 = 1, 6      DO 370 I3 = 1, I4      I34 = I34 + 1      DO 370 I2 = 1, I3      I234 = I234 + 1      UFAC = U2V(J,I234,N)      IF (UFAC .NE. 0.0) THEN        DO 360 I5 = 1, 6        UST(I5,I34,N+1) = UST(I5,I34,N+1) + UFAC*SI(I2,I5)  360   CONTINUE      ENDIF  370 CONTINUE  380 CONTINUECC     MULTIPLY US X SI TO GET DOUBLE MATRIX PRODUCT USSC      DO 400 N = 1, NP1      DO 385 I23 = 1, 21      DO 385 I4 = 1, 6      USS(I23,I4,N) = 0.0  385 CONTINUEC      I34 = 0      DO 400 I4 = 1, 6      DO 400 I3 = 1, 6      I34 = I34 + 1      DO 400 I2 = 1, I3      UFAC = UST(I2,I34,N)      IF (UFAC .NE. 0.0) THEN        DO 390 I6 = 1, 6        I26 = INDEX2(I2,I6)        USS(I26,I4,N) = USS(I26,I4,N) + UFAC*SI(I3,I6)  390   CONTINUE      ENDIF  400 CONTINUECC     MULTIPLY USS X SI TO GET USSSC      DO 440 N = 1, NP1      DO 410 I234 = 1, 56      USSS(I234,N) = 0.0  410 CONTINUEC      DO 430 I4 = 1, 6      I23 = 0      DO 430 I3 = 1, 6      DO 430 I2 = 1, I3      I23 = I23 + 1C      UFAC = USS(I23,I4,N)      IF (UFAC .NE. 0.0) THEN        DO 420 I7 = 1, 6        I237 = INDEX3(I2,I3,I7)        USSS(I237,N) = USSS(I237,N) + UFAC*SI(I4,I7)  420   CONTINUE      ENDIF  430 CONTINUE  440 CONTINUECC     MATRIX PRODUCT OF US AND SIC      DO 460 N = 1, NP1      DO 450 L2 = 1, 6      SS = 0.0      DO 445 L1 = 1, 6      SS = SS + USX(L1,N)*SI(L1,L2)  445 CONTINUE      USSC(L2,N) = SS  450 CONTINUE  460 CONTINUECC     CROSS PRODUCT BETWEEN FIRST AND THIRD ORDERC      DO 500 N1 = 1, NP1      DO 500 N2 = 1, NP1      RSSU = 0.0      USSR = 0.0C      IF (K .LT. 5) THEN        DO 470 L1 = 1, 6        RSSU = RSSU + RSX(L1,N1)*USX(L1,N2)   470   CONTINUE      ENDIFC      IF (J .LT. 5) THEN        DO 480 L1 = 1, 6        USSR = USSR + USX(L1,N1)*RSX(L1,N2)  480   CONTINUE      ENDIFCC     MATRIX PRODUCT OF US TIMES SI AND USC      USSISU = 0.0      DO 485 L1 = 1, 6      USSISU = USSISU + USSC(L1,N1)*USX(L1,N2)  485 CONTINUECC     PRODUCT OF USSS AND UC2C      USSSU = 0.0      I234 = 0      DO 490 I4 = 1, 6      DO 490 I3 = 1, I4      DO 490 I2 = 1, I3      I234 = I234 + 1      IF (N1 .EQ. 1) THEN        UFAC = - UC2(J,I234)      ELSE        UFAC = U2V(J,I234,N1-1)      ENDIF      IF (UFAC .NE. 0.0) THEN        USSSU = USSSU + 6.0*UFAC*USSS(I234,N2)      ENDIF  490 CONTINUE      CA(N1,N2) = CA(N1,N2)      1          + CW*(RSSU + USSR + USSISU + USSSU)/UBEAM(J)**2  500 CONTINUE      RETURNCC     ILLEGAL CONSTRAINTC  900 WRITE (NOUT,9804) 9804 FORMAT (' *** ERROR *** ILLEGAL FORM OF CONSTRAINT')      COC = 0.0      RETURN      END